import{_ as i,l as o,o as e,c as s,v as l,p as d,x as t,d as n,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"DP-SGD","description":"","frontmatter":{"title":"DP-SGD","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dp-sgd.md","filePath":"llm/dp-sgd.md","lastUpdated":1789023840000}'),h={name:"llm/dp-sgd.md"};function D(A,a,P,c,_,E){const r=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="dp-sgd" tabindex="-1">DP-SGD <a class="header-anchor" href="#dp-sgd" aria-label="Permalink to &quot;DP-SGD&quot;">​</a></h1><div class="epigraph"><p>裁剪再加噪，换的是对单个训练样本的不可区分。预算花完之前，提取变难；预算不是版权许可证。</p><footer>—— Abadi et al., Deep Learning with Differential Privacy；Dwork 差分隐私</footer></div><p><a href="/llm/memorization-copyright">上一课</a>给出可提取的记忆。本课补训练期工具：DP-SGD——对每样本（或每微批）梯度裁剪，再加高斯噪声，用会计追踪 \\((\\varepsilon,\\delta)\\)。缺口不是再讲一遍 AdamW，而是：普通 SGD 对重复样本的梯度可以任意大，DP 把个体影响封顶。后课模型提取是针对已部署接口，不依赖训练是否 DP。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/membership-extraction">成员推断与提取</a> 利用的是「这个样本把参数拽向自己」。差分隐私要求：换掉任意一个样本，输出分布不可区分到 \\(\\varepsilon\\) 级。缺口是把这句话落到大模型微调：全参预训练的 DP 成本极高，实践多在微调、小批次、或 DP-FTRL 变体上。本课只钉 SGD 这一条经典路径。</p><p><span class="marginnote">\\(\\varepsilon\\) 小不是「模型不记得语料」。高频模式、公共知识仍在。DP 保护的是个体记录的可证明影响，不是语义遗忘。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每步：算每样本梯度（或用泊松采样的批次），\\(\\ell_2\\) 裁剪到 \\(C\\)，平均后加 \\(\\mathcal{N}(0,\\sigma^2 C^2 I)\\)，再交给优化器。会计（RDP / 经济会计）根据步数、批次、\\(\\sigma\\) 给出 \\(\\varepsilon\\)。超参：过大 \\(C\\) 等于没裁剪；过小 \\(C\\) 加过强噪声，效用崩。语言模型通常先非 DP 预训练，再 DP 微调敏感数据。</p>',8)),(e(),d(m,null,{default:t(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E6%AF%8F%E6%A0%B7%E6%9C%AC%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20CLIP%5B%22%E2%84%932%20%E8%A3%81%E5%89%AA%22%5D%0A%20%20CLIP%20--%3E%20NOISE%5B%22%E9%AB%98%E6%96%AF%E5%99%AA%E5%A3%B0%22%5D%0A%20%20NOISE%20--%3E%20ACC%5B%22%E9%9A%90%E7%A7%81%E4%BC%9A%E8%AE%A1%20%CE%B5%22%5D%0A%20%20NOISE%20--%3E%20UPD%5B%22%E5%8F%82%E6%95%B0%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>裁剪限制单个样本对平均梯度的贡献；噪声把剩余贡献淹没到不可区分。组合定理允许很多步，但 \\(\\varepsilon\\) 累积。与 <a href="/llm/memorization-copyright">记忆化</a> 的关系：DP 降低「因这一条记录而可提取」的可能，不阻止模型生成合法的公共短句。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>DP 不是版权方案，不是对越狱的防御，也不是校准。效用–隐私曲线在 LLM 上很陡，报告必须同时给下游能力与 \\(\\varepsilon\\)。下一课模型提取假定对手只有 API，即使训练非 DP 也可以蒸馏行为。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DP-SGD：裁剪 + 噪声 + 会计，限制单样本影响。</li><li>实践多在微调；预训练 DP 贵。</li><li>不替代许可与去重。</li><li>出处：Abadi et al. CCS 2016；Dwork 差分隐私。</li></ul>',6))])}const u=i(h,[["render",D]]);export{S as __pageData,u as default};
